import React from 'react';
import ReactDOM from 'react-dom/client';

const rootElement = document.getElementById('root');

if (rootElement) {
  const root = ReactDOM.createRoot(rootElement);
  root.render(
    <React.StrictMode>
      <div style={{ color: 'white', background: '#111', padding: '40px', fontSize: '24px' }}>
        Teste Direto: O React está a renderizar!
      </div>
    </React.StrictMode>
  );
}
